/** A known festival takes precedence; invalid keys safely return the requested main scene. */
export function getCapScene({ chapterIndex = 0, festivalId = null } = {}) {
  if (typeof festivalId === 'string') {
    const festival = CAP_SCENES.find(scene => scene.festivalId === festivalId);
    if (festival) return festival;
  }
  const index = Number.isInteger(chapterIndex) && chapterIndex >= 0 && chapterIndex < 6 ? chapterIndex : 0;
  return CAP_SCENES[index];
}
